#include <stdio.h>

int main(void) {
    /* 完全二叉树按层序放进数组，下标从 0 开始 */
    int t[] = {1, 2, 3, 4, 5, 6, 7};
    int n = 7;
    printf("数组: ");
    for (int i = 0; i < n; i++) printf(" %d", t[i]);
    printf("\n");
    printf("父子下标关系（父=(i-1)/2, 左=2i+1, 右=2i+2）:\n");
    for (int i = 0; i < n; i++) {
        int p = (i - 1) / 2, L = 2 * i + 1, R = 2 * i + 2;
        printf("  i=%d val=%d | 父=%s", i, t[i], i == 0 ? "无(根)" : "");
        if (i != 0) printf("%d(val=%d)", p, t[p]);
        printf(" | 左=");
        if (L < n) printf("%d(val=%d)", L, t[L]); else printf("无");
        printf(" | 右=");
        if (R < n) printf("%d(val=%d)", R, t[R]); else printf("无");
        printf("\n");
    }
    printf("说明: 数组表示只在完全二叉树上无空洞；一般二叉树用数组会浪费 2^h 空间\n");
    return 0;
}
